+- (NSArray<NSPasteboardType> *)readablePasteboardTypes
+{
+	NSMutableArray *result = [[super readablePasteboardTypes] mutableCopy];
+	[result insertObject:UTTypeTot atIndex:0];
+	[result addObject:UTTypeMarkdown];
+	return [result copy];
+}
